_G.CoreSuiteNouveautes = {
    { cle = "s3.0", titre = "3.0 : GloryCore et l'itinéraire qui choisit", periode = "28/11 au 28/11/2026", resume = "GloryCore rejoint la suite (des points pour chaque haut fait, des objectifs à votre rythme réel). L'itinéraire de QuestCore pèse les visites, les sacs et les rendus pour choisir le meilleur ordre. Toutes les fenêtres partagent le même pied : Commandes, Aide, Dernière mise à jour, Réglages, Fermer.", versions = {
        { v = "3.0.1", date = "28/11/2026", titre = "Itinéraire de zone et GloryCore plus justes", blocs = {
            { "p", "Correctif : l'itinéraire de zone reste dans sa zone, et GloryCore compte plus juste." },
            { "h", "QuestCore" },
            { "li", "**Itinéraire de zone.** Une quête finie qui se rend hors de la zone (en ville, par exemple) se fait en quittant la zone, plus au milieu du parcours. Elle passe dans un groupe à part du suivi, « À rendre en quittant la zone », avec le lieu, et la mention « ouvre une suite » quand son rendu en débloque une." },
            { "li", "**Toutes les quêtes à prendre de la zone** sont visées, plus seulement les quatre suivantes : l'itinéraire mène chez leurs donneurs dans l'ordre le plus rentable." },
            { "li", "**Le retour compte.** Dans tous les itinéraires, partir loin pour une seule action coûte maintenant le chemin du retour vers tout ce qui reste à faire." },
            { "li", "**Quêtes de bas niveau.** Quand le suivi des quêtes de bas niveau du jeu est allumé (menu de la minicarte), les quêtes grises comptent comme les autres : carte, quêtes disponibles, itinéraires." },
            { "h", "GloryCore (bêta)" },
            { "li", "**Des points sur un maximum.** Mon compte, chaque personnage et chaque catégorie affichent « X / Y points ». Le maximum d'un personnage dépend de son camp, de sa race, de sa classe et de ses métiers." },
            { "li", "**Suites de quêtes.** Seules les suites de quêtes de classe rapportent des points ; les suites du jeu ordinaire ne sont plus des hauts faits." },
            { "li", "**Paliers.** Un haut fait de 10 points à 10, 25, 50, 75 et 100 % en exploration, rares, objets, quêtes et donjons. Ceux déjà atteints sont comptés sans être annoncés." },
            { "li", "**Boss déjà vaincus.** Les victoires notées par le Journal des donjons pour chaque personnage comptent, même d'avant GloryCore, ainsi que les boss que des quêtes rendues demandaient de tuer." },
            { "li", "**Portraits des boss.** Chaque boss a son vrai portrait dans le détail d'un donjon (pris au Journal des donjons, sans l'ouvrir), en gris tant qu'il n'est pas vaincu." },
            { "li", "**Objets à sa portée.** Pour un personnage, seuls comptent les armures et les armes que sa classe peut porter (un mage n'a plus ni maille ni plaque)." },
            { "li", "Le point d'exclamation des quêtes est plus petit dans son anneau." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 3.0.1 ; AuraCore, ClassCore et GloryCore 3.0.1 (bêta)." },
        } },
        { v = "3.0.0", date = "28/11/2026", titre = "GloryCore, itinéraire qui choisit, pied commun", blocs = {
            { "p", "Une nouvelle étape pour la suite : GloryCore arrive, l'itinéraire de QuestCore choisit lui-même le meilleur ordre, et toutes les fenêtres partagent le même pied, avec l'aide, les commandes et l'histoire de chaque version." },
            { "h", "GloryCore (bêta) : finir le jeu, en points" },
            { "p", "GloryCore remplace AchievementCore, qui n'a jamais été publié et n'existe plus. Il prend place dans la colonne de gauche, au-dessus de StuffCore. On l'ouvre aussi avec `/glorycore` ou `/ach`." },
            { "li", "**Des points pour chaque haut fait, selon son ampleur.** Une zone de quêtes finie vaut 25 points, une suite ou un thème de quêtes 10, une zone explorée 10, un donjon 10, un raid 25, un rare 10, une collection d'objets complète 50, un métier complet 25, une race ou une classe 10, une réputation 25, un rang JcJ 25, un élément d'héritage 10. En chemin, chaque palier d'un métier et chaque palier de niveau d'une classe (10, 20... 60) rapporte 5 points." },
            { "li", "**Mon compte.** Les points de tous vos personnages, les derniers hauts faits obtenus avec leur icône, puis chaque catégorie avec son anneau d'avancement." },
            { "li", "**Mon personnage.** La même page pour le personnage choisi dans la bande du haut, avec sa bannière à la couleur de sa classe." },
            { "li", "**Mes objectifs.** Le niveau visé (de 5 en 5) avec une estimation tirée de votre vrai rythme : l'XP gagnée par niveau est mesurée, et les pauses comptent au plus 10 minutes. Puis vos objectifs et vos parcours, chacun avec son bouton pour être guidé." },
            { "li", "**Les catégories.** Exploration, quêtes (par zone, avec le niveau), donjons et raids, rares du monde (par continent), objets, métiers, races et classes, réputations, JcJ et héritage. En tête de chaque catégorie : tous vos personnages, votre camp, l'autre camp, puis la carte de votre personnage, qui ouvre son détail." },
            { "li", "**Chaque donjon en entier.** Tous ses boss (lus dans le Journal des donjons de Forever quand il est installé), tous ses rares et toutes ses quêtes : un donjon n'est fini que quand tout est fait. Les boss et les rares tués sont relevés dans le journal de combat." },
            { "li", "**Les métiers par palier.** Un haut fait par palier de métier, avec le rang atteint et les recettes connues." },
            { "li", "**L'annonce d'un haut fait.** Un bandeau qui clignote, reste un instant puis part en fondu, avec l'icône du haut fait et ses points, et le son du passage de niveau. Votre personnage danse une fois arrêté, jamais en combat. Le bandeau et la danse ont chacun leur case dans les Paramètres de GloryCore, actifs par défaut." },
            { "li", "**Une présentation en cartes.** Une seule grille de trois cartes par rangée, une image ronde alignée sur le nom, une ligne principale, une sous-ligne et une barre dessous. La couleur dit l'état : la couleur de la classe pour un personnage, une échelle de paliers sinon, le vert à 100 %. Le personnage connecté passe toujours en premier." },
            { "li", "**Navigation.** Les flèches en haut à droite reviennent sur ce que vous avez regardé. À la manette, la croix gauche et droite change de personnage, B remonte puis ferme." },
            { "h", "QuestCore : un itinéraire qui choisit le meilleur ordre" },
            { "li", "**La cible suivante est choisie par rentabilité.** L'itinéraire pèse les visites regroupées (plusieurs quêtes au même endroit), les rendus qui ouvrent une suite, la place dans les sacs et dans le journal, la montée de niveau, et une valeur qui baisse avec le temps. Il prévoit trois visites d'avance et ne change pas d'avis pour un écart minime." },
            { "li", "**Les vrais sacs.** Le calcul compte la place libre réelle, la place que prendra le butin à venir, et les objets gris qu'on peut jeter. Un vendeur, un réparateur, une boîte aux lettres ou un maître de vol proche d'une visite entre dans le plan quand il le faut." },
            { "li", "**Presque fini sur place.** Une quête à qui il manque peu, dans la zone où vous êtes, se termine avant de partir." },
            { "li", "**Sacs presque pleins.** La suite propose d'aller rendre un groupe de quêtes, vous y guide, puis reprend l'itinéraire là où il en était. Rien n'est proposé si l'itinéraire y allait déjà." },
            { "li", "**Le plan en direct dans le suivi.** En tête de l'itinéraire : « Maintenant », puis « Ensuite ». Les quêtes à rendre passent sous celles à faire, et celles d'un autre continent sont mises de côté en bas, avec la raison." },
            { "li", "**Le compte suit l'étape visée** de l'itinéraire, et seules les quatre prochaines quêtes à prendre sont visées, dans l'ordre du parcours." },
            { "li", "**Itinéraire de zone.** Il s'ouvre aussitôt créé, avec son bouton « Me guider ». Son infobulle montre la zone, les récoltes à votre rang dans vos métiers et les composants qui manquent à vos projets CraftCore." },
            { "h", "Toute la suite" },
            { "li", "**Un seul pied pour toutes les fenêtres.** À gauche, Commandes et Aide ; au milieu, Dernière mise à jour ; à droite, Réglages et Fermer." },
            { "li", "**Dernière mise à jour.** Une fenêtre au-dessus de tout : chaque version depuis la 1.0.0, regroupée par série, à déplier, avec ce qu'elle a apporté." },
            { "li", "**Aide.** L'aide de l'add-on ouvert, en commençant par la page affichée quand elle a la sienne. CraftCore garde son aide de page et son didacticiel. À la manette, Y ouvre l'aide partout." },
            { "li", "**Commandes.** Les touches de la fenêtre, celles de la manette pour toute la suite, le clavier et les commandes de discussion de chaque add-on installé. Dans la fenêtre, LB et RB passent d'un onglet à l'autre." },
            { "li", "**Réglages généraux sur votre fond.** Le parchemin que vous avez choisi (ou la roche grise), rogné pour tenir dans la fenêtre, jamais étiré ni tassé. Il remplace le panneau bleu." },
            { "li", "**Icônes de classe rondes.** L'icône de classe du jeu (celle de la recherche de groupe), dans un anneau à la couleur de la classe, partout sauf dans le suivi des quêtes. Tous les cercles ont la même taille ; les personnages non choisis passent en gris." },
            { "li", "**Votre portrait dans le cercle de votre classe**, partout où il apparaît : stocks de CraftCore, LegacyCore, GloryCore." },
            { "li", "**Bande des personnages** dans toutes les fenêtres à pages, 10 % plus petite." },
            { "h", "CraftCore" },
            { "li", "Une recette retirée d'un projet ne reste plus affichée comme faite dans Mes fabrications." },
            { "li", "Un maître n'est proposé que s'il enseigne vraiment la recette (la suite relève ce que chaque maître enseigne). Les recettes du camp des caisses sont proposées chez leur vendeur." },
            { "h", "Corrections" },
            { "li", "GloryCore : B ferme de nouveau la fenêtre après un passage par les raccourcis de MacroCore." },
            { "li", "GloryCore : plus de barre posée sur un texte, plus de libellé coupé dans le menu (« Mes objectifs »)." },
            { "li", "GloryCore : un métier restait à 0 point tant que son dernier rang n'était pas atteint ; chaque palier compte désormais." },
            { "li", "GloryCore : prendre un niveau ne rapportait aucun point ; chaque palier de niveau d'une classe est un haut fait." },
            { "h", "Ajustements de l'itinéraire pendant le développement" },
            { "p", "Pour les lecteurs attentifs : une règle essayée en cours de route, « une quête finie se rend d'abord », a été retirée. Elle faisait faire des allers-retours. La règle qui la remplace : une quête finie se rend quand l'itinéraire passe près de son donneur, ou quand les sacs l'exigent, et le guidage reprend ensuite." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 3.0.0 ; AuraCore, ClassCore et GloryCore 3.0.0 (bêta)." },
        } },
    } },
    { cle = "s2.5", titre = "2.5 : ClassCore, les caisses et le commerce", periode = "26/11 au 27/11/2026", resume = "ClassCore arrive en bêta (quêtes de classe, sorts, talents, familiers). CraftCore gagne le rang visé refondu, l'hôtel des ventes à la manette, les formateurs, le commerce des caisses et le commerce entre joueurs ; QuestCore, les détours dans l'itinéraire.", versions = {
        { v = "2.5.6", date = "27/11/2026", titre = "Détours, commerce des caisses et entre joueurs", blocs = {
            { "p", "QuestCore : des détours dans l'itinéraire. CraftCore : le commerce des caisses, le commerce entre joueurs (bêta), Mes recettes allégée." },
            { "h", "QuestCore" },
            { "li", "**Détours.** Pendant un guidage, une quête à rendre qui n'en fait pas partie s'ajoute à l'itinéraire d'un clic sur sa petite carte. La flèche fait le détour au bon moment, puis reprend la route. Recliquer le retire ; il part aussi quand la quête est rendue ou quand le guidage s'arrête." },
            { "li", "**Quêtes sans objectif.** Une quête « allez voir quelqu'un » compte comme à rendre : elle entre dans les rendus et dans les détours." },
            { "h", "CraftCore" },
            { "li", "**Commerce des caisses (onglet Caisses).** Réputation du camp, faveur marchande, une chose à faire avec son guidage, écrits d'artisan, patrons du camp (rang requis, niveau, prix, état, coche de progression, prix de l'hôtel des ventes au survol) et récompenses. Alliance et Horde." },
            { "li", "**Une caisse, un lot.** Une caisse se remplit avec un seul de ses lots. « Projet » la met dans Mes fabrications (onglet Caisses) avec tous ses lots ; vos autres personnages se voient proposer l'envoi au courrier ; « Assembler » quand un lot est complet dans les sacs." },
            { "li", "**Avec mon groupe (bêta).** Ce que les joueurs du groupe savent fabriquer, commandes entre joueurs, panneau à l'échange. Réglages : partager ce que je sais fabriquer, groupe simulé." },
            { "li", "**Mes recettes.** Triées par chance de faire monter le métier ; ce qui manque et le prix de l'hôtel des ventes passent dans l'infobulle." },
            { "li", "**Courrier.** L'enveloppe de la minicarte dit ce que vos personnages vous ont envoyé et ce qui restait dans la boîte." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.6 ; AuraCore 2.5.6 (bêta) ; ClassCore 2.5.6 (bêta)." },
        } },
        { v = "2.5.5", date = "26/11/2026", titre = "Où apprendre une recette", blocs = {
            { "p", "CraftCore : où apprendre une recette, et projets commerciaux réglables." },
            { "h", "CraftCore" },
            { "li", "**Chez quel formateur.** Une recette qui s'apprend chez un formateur dit lequel : celui de son palier (compagnon, expert, artisan), le plus proche, avec sa zone." },
            { "li", "**Me guider.** Chaque recette à apprendre a son bouton « Me guider », vers le formateur ou vers le marchand qui vend son plan." },
            { "li", "**Hôtel des ventes, Recettes.** Les recettes que votre plan prévoit d'apprendre passent en tête, en vert, marquées « dans mon plan »." },
            { "li", "**Projet commercial.** Avant de le créer, une fenêtre propose la quantité de chaque recette, par défaut le maximum faisable. Elle se centre sur le panneau de l'hôtel des ventes et prend la manette." },
            { "li", "**Corrections.** Un objet vendu par un marchand rare reste proposé à l'hôtel des ventes ; ce qui se vend partout ne compte que ce que le personnage a lui-même." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.5 ; AuraCore 2.5.5 (bêta) ; ClassCore 2.5.5 (bêta)." },
        } },
        { v = "2.5.4", date = "26/11/2026", titre = "Rang visé et hôtel des ventes refondus", blocs = {
            { "p", "Refonte du rang visé de CraftCore et du panneau de l'hôtel des ventes." },
            { "h", "CraftCore : rang visé" },
            { "li", "**Plan figé.** Le plan d'un rang visé est calculé une fois, quand l'objectif est posé, puis enregistré avec ses étapes et ses quantités. Il ne change plus tout seul." },
            { "li", "**Tout dès le départ.** Le besoin complet est annoncé tout de suite ; acheter ou fabriquer ne peut que le faire baisser." },
            { "li", "**Recettes sûres d'abord.** Les recettes oranges passent toujours en premier (d'abord celles dont vous avez les composants), puis les jaunes, la plus forte chance d'abord." },
            { "li", "**Un dé devant le rang** quand il dépend de la chance, dans la fenêtre principale et dans Mes fabrications. Une malchance au-delà de la marge prévue est dite clairement." },
            { "li", "**Avancement réel.** Les étapes avancent avec le rang réel et les fabrications réussies ; une étape faite reste faite, à sa place." },
            { "li", "**Créer ne s'active qu'à 100 %** : tout réuni et dans les sacs." },
            { "li", "Les étapes de récolte s'appellent « Récolter ou acquérir »." },
            { "h", "CraftCore : hôtel des ventes" },
            { "li", "**Panneau refait** avec le fond de l'hôtel des ventes, plus large, en tableaux à colonnes alignées." },
            { "li", "**À acheter** : ce qui manque à vos rangs visés et à vos projets, objectif par objectif, avec le manque, le prix à l'unité, le total et Chercher. Un objet vendu par un marchand rare reste proposé." },
            { "li", "**Vendre** : tout ce qui se vend dans vos sacs (sauf munitions et composants de classe), avec quantité, prix à l'unité et total." },
            { "li", "**Ce qui rapporte** : tout ce que vous savez fabriquer, par métier, le mieux payé d'abord, avec bénéfice et quantité faisable. Cochez des recettes pour créer un projet commercial, avec le gain estimé au prix du moment." },
            { "li", "**Recettes** : par métier, du rang le plus bas au plus haut." },
            { "li", "Plus de blocage du jeu pendant les relevés de prix." },
            { "h", "Corrections" },
            { "li", "Les achats sont comptés dès que les sacs sont relus." },
            { "li", "À la manette, la croix atteint aussi les onglets de Mes fabrications." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.4 ; AuraCore 2.5.4 (bêta) ; ClassCore 2.5.4 (bêta)." },
        } },
        { v = "2.5.3", date = "26/11/2026", titre = "Plus de blocage à l'hôtel des ventes", blocs = {
            { "p", "Correction d'un blocage du jeu à l'hôtel des ventes." },
            { "h", "CraftCore" },
            { "li", "**Hôtel des ventes.** Le panneau recalculait les plans de tous vos personnages à chaque prix relevé et à chaque mouvement des sacs : à l'hôtel des ventes, ces calculs s'empilaient jusqu'à figer le jeu. Les plans sont maintenant gardés tant que rien ne change, et le panneau se recalcule au plus une fois toutes les 0,7 seconde." },
            { "li", "**Mouchard de lenteur.** Un calcul anormalement long est signalé dans la discussion et noté pour analyse." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.3 ; AuraCore 2.5.3 (bêta) ; ClassCore 2.5.3 (bêta)." },
        } },
        { v = "2.5.2", date = "26/11/2026", titre = "Modèles de talents personnels", blocs = {
            { "p", "Modèles de talents personnels dans ClassCore, et corrections de CraftCore." },
            { "h", "ClassCore (bêta)" },
            { "li", "**Mes modèles.** Dans la simulation, « Enregistrer » garde vos points sous un nom et une activité, pour tous vos personnages de la classe." },
            { "li", "**Exporter et importer.** Un code à copier pour échanger un modèle. L'import accepte aussi les liens wowforevertalent, talentsforever et Warcraft Tavern." },
            { "li", "**Partager.** Un modèle s'envoie à votre guilde ou à votre groupe (joueurs qui ont ClassCore). Ceux reçus arrivent dans « Modèles reçus » : Garder ou Supprimer." },
            { "li", "**Proposer un modèle.** Un formulaire sur GitHub pour faire entrer un modèle dans les modèles conseillés." },
            { "h", "CraftCore" },
            { "li", "**Rang visé.** Le plan ne change plus quand vos stocks changent : le besoin annoncé est complet dès le départ et chaque achat le réduit, sans en ajouter. Les recettes dont vous aviez les composants restent en tête." },
            { "li", "**Caisses.** Les objets sont reconnus malgré les majuscules et les accents (églantine, étoffe de lin) ; les matériaux de base ont leur icône même à zéro." },
            { "li", "**Marchands.** Plus de ralentissement : un seul recalcul par série de mises à jour du marchand." },
            { "li", "**Manette.** Fermer l'hôtel des ventes, la banque ou le courrier rend les touches Y et X au jeu." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.2 ; AuraCore 2.5.2 (bêta) ; ClassCore 2.5.2 (bêta)." },
        } },
        { v = "2.5.1", date = "26/11/2026", titre = "ClassCore et CraftCore enrichis", blocs = {
            { "p", "Mise à jour de ClassCore (bêta) et de CraftCore, avec quelques corrections." },
            { "h", "ClassCore (bêta)" },
            { "li", "**Talents comme dans le jeu.** Les trois arbres complets, avec les cadres, les chiffres et les flèches de la fenêtre de talents. Liste Principale / Secondaire (une fois débloquée)." },
            { "li", "**Simulation.** Sur la même page : clic pour placer un point, clic droit pour le retirer, niveau du personnage réglable. Rien n'est appris : c'est un essai." },
            { "li", "**Modèles conseillés.** Par activité (montée de niveau, donjons en montée, raids et donjons au 60, JcJ) et par spécialisation, d'après les guides publiés pour Forever. Un modèle se charge dans la simulation et indique votre prochain point." },
            { "li", "**Sorts de classe.** Une ligne par rang, dans l'ordre d'apprentissage : niveau, coût, apprentissage, état." },
            { "li", "**Où apprendre.** Votre maître de classe le plus proche (et celui des familiers pour un chasseur) : sur la carte de MapCore, ou guidage." },
            { "li", "**Familiers.** Le cadre du modèle 3D prend la couleur de la bête : argent pour une rare, or pour une élite." },
            { "h", "CraftCore" },
            { "li", "**Chez un marchand.** Le panneau de CraftCore s'ouvre à côté de tout marchand qui vend ce qui manque à vos fabrications (fioles, plans...). Un clic achète la quantité exacte." },
            { "li", "**Paliers de métier.** Au rang maximum, le guide indique le palier suivant, le niveau requis et tous les maîtres qui l'enseignent, avec ce que chaque zone offre en plus et un guidage pour chacun. Un avis prévient aussi quand le niveau du personnage bloque la suite, puis quand il est atteint." },
            { "li", "**Hôtel des ventes.** Le relevé des prix en haut de chaque onglet ; un objet acheté ou arrivé au courrier ne manque plus ; munitions et composants de classe ne sont plus proposés à la vente." },
            { "li", "**Envoi à vos personnages.** Chaque objet a sa case, cochée par défaut : décochez ce que vous ne voulez pas envoyer." },
            { "li", "**Mes fabrications.** Les étapes faites restent en vert et la fenêtre ne change plus de hauteur pendant que vous fabriquez." },
            { "h", "LegacyCore" },
            { "li", "Les arbres d'héritage reprennent le style des talents de ClassCore." },
            { "li", "« Ouvrir l'héritage » ouvre la fenêtre du jeu par un clic de souris, sans la bloquer." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.1 ; AuraCore 2.5.1 (bêta) ; ClassCore 2.5.1 (bêta)." },
        } },
        { v = "2.5.0", date = "26/11/2026", titre = "ClassCore (bêta) et icônes encadrées", blocs = {
            { "p", "Amélioration significative : un nouvel add-on, ClassCore (bêta), et l'encadrement des icônes du jeu dans toute la suite." },
            { "h", "Points forts" },
            { "li", "**ClassCore (bêta), votre classe en un coup d'œil.** Les quêtes de classe en suites numérotées (faites, à prendre, plus tard, avec le guidage de QuestCore), tous les sorts du maître par arbre avec leur niveau et leur coût, les arbres de talents, les objets de classe sur vous et en banque, et une pastille sous le portrait (fragments d'âme, munitions, runes, formes du druide). Tous vos personnages depuis la barre du haut, sans changer de personnage." },
            { "li", "**Le catalogue des familiers du chasseur.** Chaque famille, chacune de ses bêtes (où la trouver, niveau, ce qu'elle apprend à votre familier, élite ou rare), avec un aperçu 3D, chaque technique rang par rang, et les familiers rares." },
            { "li", "**Manette au courrier, à la banque et à l'hôtel des ventes.** Le double carré entre dans le panneau de CraftCore, sans aucune touche prise au jeu." },
            { "h", "Et aussi" },
            { "li", "Les icônes carrées de la suite reprennent le cadre des boutons d'action du jeu." },
            { "h", "Compléments" },
            { "li", "**ClassCore** rejoint les compléments, en version bêta. Vos retours sont les bienvenus dans l'onglet Issues." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.5.0 ; AuraCore 2.5.0 (bêta) ; ClassCore 2.5.0 (bêta)." },
        } },
    } },
    { cle = "s2.1", titre = "2.1 : monter un métier, vraiment guidé", periode = "26/11 au 26/11/2026", resume = "Un plan figé pour monter un métier, proposé et jamais imposé, des séries de fabrication complètes, la vente à l'hôtel des ventes depuis CraftCore, et la manette dans toutes les petites fenêtres.", versions = {
        { v = "2.1.1", date = "26/11/2026", titre = "Manette libre au courrier et à la banque", blocs = {
            { "p", "Correctif." },
            { "li", "Courrier et banque : plus aucune touche de la manette prise par CraftCore pendant que la fenêtre est ouverte (le jeu bloquait une de ses propres actions). Les boutons du panneau se cliquent avec le curseur de la manette du jeu." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.1.1 ; AuraCore 2.1.1 (bêta)." },
        } },
        { v = "2.1.0", date = "26/11/2026", titre = "CraftCore et guidage nettement améliorés", blocs = {
            { "p", "Amélioration significative de CraftCore et du guidage, et beaucoup de petites finitions." },
            { "h", "Points forts" },
            { "li", "**Monter un métier, vraiment guidé.** Le plan d'un rang visé est figé dès qu'on le choisit : rien ne change sans votre accord. Une recette apprise entre-temps ? Un autre plan est seulement proposé (plan actuel contre nouveau plan, à garder ou à changer). Le guide passe d'abord par ce que vous avez déjà, indique les recettes à apprendre (et à partir de quel rang), et ne bloque jamais la fabrication d'ici là." },
            { "li", "**Séries de fabrication complètes**, avec la barre de fabrication du jeu à la place du bouton pendant la série." },
            { "li", "**Hôtel des ventes.** Le panneau de CraftCore a deux onglets : Prix et achats, et Vendre (ce que vos sacs peuvent vendre, prix à l'unité et total). Préparer pose la pile dans la vente du jeu ; Vendre met en vente directement au dernier prix relevé." },
            { "li", "**Quêtes et métiers reliés.** Une quête qui demande un objet qu'aucun monstre ne donne dit comment l'obtenir : en stock, à fabriquer (par qui), chez un marchand, ou au prix relevé à l'hôtel des ventes. Les recettes utiles à une quête portent un point d'exclamation, et les métiers qui utilisent leur produit sont indiqués." },
            { "li", "**Guidage plus sûr.** Un guidage ne s'arrête plus sur un état passager (niveau gagné, journal relu). Un trajet de donjon recréé garde son avancement." },
            { "li", "**Manette.** Le double carré entre dans les petites fenêtres de CraftCore (banque, courrier, hôtel des ventes, consignes), sans rien régler, puis on y navigue à la croix." },
            { "h", "Et aussi" },
            { "li", "Plus aucune action bloquée par le jeu au courrier et à la banque." },
            { "li", "Infobulles plus courtes et hiérarchisées, quantités dans l'ordre (moins, puis plus), fenêtres de dialogue centrées et fermées d'une touche." },
            { "li", "Nombreuses corrections d'affichage et d'alignement." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.1.0 ; AuraCore 2.1.0 (bêta)." },
        } },
    } },
    { cle = "s2.0", titre = "2.0 : une suite refondue", periode = "25/11 au 25/11/2026", resume = "Une seule interface pour tous les add-ons, un personnage égale une seule fiche, et un guidage qu'on comprend et qu'on peut toujours annuler.", versions = {
        { v = "2.0.1", date = "25/11/2026", titre = "Guidage des suites de quêtes", blocs = {
            { "p", "Correctif." },
            { "li", "Suivi des métiers : les quantités des matières restent alignées après un achat ou une récolte." },
            { "li", "Guidage des suites de quêtes : le compte avance à chaque geste (prendre, faire, rendre), ce qui est commencé passe d'abord, et une ligne dit quoi faire à l'étape visée." },
            { "li", "Objectifs inconnus de la base (quêtes propres au serveur) : guidés vers le point montré par la carte du jeu." },
            { "li", "Quête à prendre de bas niveau signalée (son « ! » peut être masqué par le jeu)." },
            { "li", "Avec un add-on d'itinéraire : son trajet n'est plus effacé et recalculé sans fin." },
            { "d", "Contenu : CraftCore, QuestCore, MapCore, LegacyCore, StuffCore, FriendsCore 2.0.1 ; AuraCore 2.0.1 (bêta)." },
        } },
        { v = "2.0.0", date = "25/11/2026", titre = "Une suite refondue", blocs = {
            { "p", "Une suite refondue : une seule interface pour tous les add-ons, un guidage qu'on comprend et qu'on peut toujours annuler, et des personnages enfin uniques." },
            { "h", "Toute la suite" },
            { "li", "**Une interface commune.** Les fenêtres de CraftCore, QuestCore, MapCore, LegacyCore et StuffCore partagent les mêmes modèles : même barre des personnages en haut, mêmes menus à gauche (rubriques titrées, lignes en retrait, ligne choisie en or), même survol, même entrée Paramètres avec la même icône, rangée en dernier sous le nom de l'add-on." },
            { "li", "**Une seule barre des personnages.** Mêmes personnages, même ordre et même aspect dans chaque fenêtre : votre personnage connecté en premier avec son vrai portrait, les autres avec l'icône de leur classe." },
            { "li", "**Un personnage = une seule fiche.** Le serveur Forever donne parfois un autre nom de royaume au même personnage, ce qui créait des doublons (un personnage affiché deux fois, avec ou sans portrait). La suite garde désormais un royaume fixe, et réunit toute seule les données d'un même personnage. Rien n'est effacé : une copie en trop est mise de côté dans une archive." },
            { "li", "**Compléments.** Un bouton Compléments en bas de la colonne de gauche ouvre les outils à part (AuraCore, FriendsCore), qui s'affichent en onglets à droite." },
            { "li", "**Manette.** Clic des sticks (L3 / R3) : les add-ons de la colonne de gauche, puis Compléments. LT / RT : d'un complément à l'autre. Croix gauche / droite : d'un personnage à l'autre, indiqué au bout de la barre des personnages. LB / RB : les rubriques du menu." },
            { "li", "**Lisibilité.** Trois tailles de police seulement. Les noms de personnages s'écrivent partout pareil, dans la couleur de leur classe, un peu approfondie sur le parchemin pour rester lisibles. Ombre portée adoucie. Plus d'orange foncé." },
            { "li", "**Fenêtres qui surgissent** (choix du guide, consignes, questions) : toujours au premier plan." },
            { "li", "**Sous-brillance** des fenêtres en mouvement : jamais en vol, et réglable." },
            { "li", "**Nouvelle version** : la suite prévient en jeu, discrètement, quand une version plus récente existe." },
            { "h", "Guidage" },
            { "li", "**Un moteur de guidage commun** : chaque bouton Guider vise un objectif précis (une quête, une suite de quêtes, un donjon, une récolte, un marchand, une tournée) et s'y tient. Le guidage reprend après un /reload." },
            { "li", "**Toujours annulable** : « Changer de guide » et « Arrêter » sous les indications du guidage. La fenêtre « Qui vous guide ? » a un bouton Annuler : au lancement, rien ne démarre ; en changeant de guide, l'ancien reprend." },
            { "li", "**Avec un add-on d'itinéraire** (Shortest Path Forever, TomTom) : les lignes de la suite (« QuestCore : … », « Étape 2 sur 10 ») se placent au-dessus de tout ce que cet add-on affiche, jamais par-dessus, dès la première seconde. Une seule flèche à la fois." },
            { "li", "Les positions et vitesses que le jeu cache (champs de bataille) ne sont plus jamais comparées." },
            { "h", "QuestCore" },
            { "li", "**Menu en rubriques** : Mon journal (En cours, À rendre, Quêtes communes, Parcours), Trouver des quêtes (Disponibles, Mon histoire, Donjons), Progression (Niveau suivant, Objectif de niveau)." },
            { "li", "**Disponibles par zone**, avec une règle de niveau claire : ce qui est pour vous (jusqu'à votre niveau + 3), le reste replié dans « Plus tard »." },
            { "li", "**Niveau suivant** : ce qu'il reste à rendre et à faire pour passer le prochain niveau. **Objectif de niveau** : un plan niveau par niveau." },
            { "li", "**Donjons réécrits** : préparation commune (suites de quêtes prérequises d'abord, puis les quêtes à prendre dehors, celles de l'intérieur seulement indiquées, puis l'entrée). Une quête déjà prise ne renvoie plus jamais chez son donneur." },
            { "li", "**Plan du donjon** dans la carte, avec les vrais portraits des boss. Le Journal des donjons ne s'ouvre jamais tout seul : il est proposé comme outil, ouvert seulement sur votre clic." },
            { "li", "Quêtes d'un autre continent visées quand même, XP estimée pour les quêtes absentes de la base, niveaux des donjons repris du Journal des donjons de Forever." },
            { "li", "La récolte quitte QuestCore (elle est dans CraftCore et MapCore). Plus de favoris." },
            { "h", "CraftCore" },
            { "li", "**Feuille de route** de chaque fabrication, présentée comme une suite de quêtes : récolter, relever le courrier, passer à la banque, aller chercher chez vos autres personnages (le plus rapide selon où ils sont), acheter, fabriquer. Une étape ne passe au vert qu'avec la preuve qu'elle est faite." },
            { "li", "**Banquiers** : désignez vos personnages banquiers (par spécialité), avec un didacticiel, des onglets par banquier, ce que chacun garde rangé par famille, et le registre des mouvements. Les envois sont préparés pour le bon banquier." },
            { "li", "**Mes fabrications** : chaque matière dit où elle se trouve (sacs, banque, courrier, autres personnages). Vert quand tout est dans vos sacs." },
            { "li", "**Rangement automatique** des composants dans les sacs spécialisés quand la banque ou la boîte aux lettres est ouverte." },
            { "li", "**Un seul moyen de guider la récolte** : la petite carte à côté de chaque fabrication (elle s'allume quand le guidage est en cours, un second clic l'arrête)." },
            { "h", "MapCore" },
            { "li", "**Onglets** Azeroth, continents et **Itinéraires** : tous vos itinéraires, par type (suites de quêtes, donjons, niveau suivant, récolte) ou par zone. Un clic guide, un second arrête. Le guidage de récolte en cours, d'où qu'il vienne, y apparaît." },
            { "li", "Cartes plus propres : les repères trop serrés sont regroupés avec leur nombre au lieu de former des cercles." },
            { "h", "LegacyCore" },
            { "li", "Menu en rubriques. Page Chronologie : le temps passé sur chaque niveau, en colonnes nettes (vert : niveau terminé, bleu : en cours, gris : avant l'installation). Le journal du compte, illisible avec beaucoup de personnages, est retiré." },
            { "h", "StuffCore" },
            { "li", "Trois paliers d'amélioration (gemme verte, jaune ou rouge au coin de l'icône), expliqués au survol." },
            { "li", "Donjons et raids rangés par instance, du meilleur palier au moins bon." },
            { "h", "AuraCore (bêta)" },
            { "li", "Tous les élixirs et flacons reconnus. Demande de buffs envoyée pendant le clic, découpée proprement, avec un chuchotement à chaque donneur." },
            { "h", "Portraits personnalisés" },
            { "li", "Déposez une image par personnage (TGA 128 x 128) dans le dossier `Interface/AddOns/SagaCorePortraits` : elle remplace l'icône de classe. Modèle et mode d'emploi dans `docs/SagaCorePortraits` du dépôt." },
            { "d", "Contenu : CraftCore 2.0.0, QuestCore 2.0.0, MapCore 2.0.0, LegacyCore 2.0.0, StuffCore 2.0.0, FriendsCore 2.0.0, AuraCore 2.0.0 (bêta)" },
        } },
    } },
    { cle = "s1.7", titre = "1.7 : un seul guidage pour toute la suite", periode = "22/11 au 24/11/2026", resume = "Un seul bouton Guider partout, le choix de qui vous guide (la flèche de la suite ou un add-on d'itinéraire), et des correctifs autour du nom du royaume.", versions = {
        { v = "1.7.3", date = "24/11/2026", titre = "Royaume des données déjà enregistrées", blocs = {
            { "p", "Correctif." },
            { "li", "Royaume : quand le jeu ne donne pas le nom du royaume, la suite garde celui sous lequel vos données sont déjà enregistrées. La 1.7.2 pouvait prendre un autre nom du même royaume et faire croire à un nouveau personnage (réglages et données invisibles). Rien n'est perdu : tout réapparaît avec cette version." },
        } },
        { v = "1.7.2", date = "23/11/2026", titre = "Royaume cherché partout", blocs = {
            { "p", "Correctif." },
            { "li", "Personnages, stuff, quêtes : tout s'enregistre de nouveau sur une installation neuve quand le jeu ne donne pas le nom du royaume. Le royaume est cherché dans toutes les fonctions du jeu, et les données passent toutes seules sous le vrai royaume dès qu'il est connu." },
        } },
        { v = "1.7.1", date = "23/11/2026", titre = "Guidage sans erreur en champ de bataille", blocs = {
            { "p", "Correctif." },
            { "li", "Guidage : plus d'erreur en boucle quand le jeu cache la vitesse ou la position du personnage (champ de bataille, combat)." },
        } },
        { v = "1.7.0", date = "22/11/2026", titre = "Un seul guidage, clair", blocs = {
            { "p", "Un seul guidage, clair, pour toute la suite." },
            { "h", "Guidage" },
            { "li", "Un seul bouton Guider, le même partout : quêtes, suites de quêtes, donjons, récolte, achats chez un marchand, tournée de récolte." },
            { "li", "À chaque guidage, une fenêtre « Qui vous guide ? » : un add-on d'itinéraire (Shortest Path Forever, TomTom) ou la flèche de la suite. Un add-on absent est grisé, le petit i explique comment l'installer." },
            { "li", "Une seule source à la fois : avec un add-on d'itinéraire, il reçoit chaque étape et la suite affiche seulement « Suivez l'itinéraire de ... » ; sinon, la flèche de la suite. Jamais les deux." },
            { "li", "« Changer de guide » sous la boussole et dans le suivi, pour passer de l'un à l'autre en route." },
            { "li", "Guider n'ouvre plus aucune carte ; « Voir sur la carte » ne fait que montrer." },
            { "li", "Ce qui est guidé se choisit tout seul : les quêtes cochées, sinon le trajet le plus court pour monter de niveau, sinon le trajet tracé, sinon les quêtes à rendre." },
            { "li", "Une quête de donjon vue de dehors : la flèche mène à l'entrée du donjon." },
            { "li", "L'icône de ce qu'on guide au centre de la boussole." },
            { "h", "QuestCore" },
            { "li", "Quêtes du donjon rangées en « Avant d'entrer », « Dans le donjon » et « Au retour » ; chaque quête de donjon le dit (« Se fait dans le donjon »)." },
            { "li", "En groupe : sous les suites, prérequis et quêtes de donjon, les membres qui les ont aussi." },
            { "h", "CraftCore" },
            { "li", "Équipement : l'objet porté se lit même quand le jeu n'a pas encore sa fiche (objets propres au serveur)." },
            { "d", "Contenu : CraftCore 0.37.0, QuestCore 0.36.0, MapCore 0.14.0, LegacyCore 0.8.1, StuffCore 0.1.0, FriendsCore 0.2.0, AuraCore 0.10.1 (bêta)" },
        } },
    } },
    { cle = "s1.6", titre = "1.6 : StuffCore et FriendsCore", periode = "22/11/2026", resume = "Deux nouveaux add-ons : StuffCore (votre équipement et d'où vient ce qui l'améliore) et FriendsCore (les add-ons d'autres auteurs qui complètent la suite).", versions = {
        { v = "1.6.0", date = "22/11/2026", titre = "StuffCore et FriendsCore, guidage plus simple", blocs = {
            { "p", "Deux nouveaux add-ons dans la suite, et un guidage plus simple." },
            { "h", "Nouveaux" },
            { "li", "StuffCore : votre équipement devient un add-on à part, dans la colonne de la suite. Seulement ce qui améliore ce que vous portez, et d'où ça vient : déjà possédé, craft (le vôtre ou celui d'un autre personnage), butins du monde, quêtes, donjons et raids. Trois présentations au choix dans ses Paramètres. Demande CraftCore." },
            { "li", "FriendsCore : une petite aide qui reconnaît les add-ons d'autres auteurs (itinéraires détaillés...) et leur confie la tâche." },
            { "h", "QuestCore" },
            { "li", "Guidage : un seul bouton Guider, le même partout. Il guide les quêtes cochées, sinon le trajet le plus court pour monter de niveau, sinon le trajet tracé, sinon les quêtes à rendre." },
            { "h", "CraftCore" },
            { "li", "Menu regroupé : l'atelier, les pages du métier choisi, tous les métiers, les paramètres." },
            { "li", "Mes stocks : recherche, un objet chez tous vos personnages avec le total, personnages à la couleur de leur classe." },
            { "li", "Monter un métier : un vrai guide (rangs de couleur exacts, recettes à apprendre en chemin), points sûrs et points au hasard séparés." },
            { "li", "Avis quand un métier atteint son rang maximum, avec un rappel près d'un maître du métier." },
            { "li", "Banque et boîte aux lettres : seuls les objets des sacs se joignent, choix de l'envoi et des actions à la manette." },
            { "li", "Caisses : affichage bien plus rapide, onglet en bas à droite." },
            { "h", "Suite" },
            { "li", "Listes déroulantes utilisables à la manette." },
            { "li", "La barre de la manette dit « Contrôler la page »." },
            { "d", "Contenu : CraftCore 0.36.0, QuestCore 0.35.0, MapCore 0.13.0, LegacyCore 0.8.0, StuffCore 0.1.0, FriendsCore 0.1.0, AuraCore 0.10.0 (bêta)" },
        } },
    } },
    { cle = "s1.5", titre = "1.5 : fabriquer, et AuraCore", periode = "21/11 au 22/11/2026", resume = "CraftCore fabrique lui-même, étape par étape, et vise plusieurs rangs à la fois. AuraCore arrive en bêta : un anneau d'améliorations autour du personnage.", versions = {
        { v = "1.5.3", date = "22/11/2026", titre = "Petits ajustements", blocs = {
            { "p", "Petits ajustements, pas de nouvelle fonction." },
            { "h", "QuestCore" },
            { "li", "Parcours : une étape rendue dont la suite continue laisse sa place à la quête suivante (en cours, à rendre ou à faire)." },
            { "li", "Suites : une quête mal reliée par la base du jeu se montre à part, sans trait." },
            { "li", "Suivi : rond, pourcentage et étoile alignés sur le titre ; l'icône de donjon ne décale plus la ligne." },
            { "li", "Infobulle d'une quête : qui l'a aussi dans le groupe, et où il en est s'il a QuestCore." },
            { "h", "AuraCore (bêta)" },
            { "li", "En combat, un aspect ou une aura sans place réservée ne disparaît plus du cercle." },
            { "h", "CraftCore" },
            { "li", "Équipement : un chiffre au plus après la virgule (dégâts par seconde)." },
            { "d", "Contenu : CraftCore 0.35.3, QuestCore 0.34.3, MapCore 0.12.3, LegacyCore 0.7.3, AuraCore 0.9.2 (bêta)" },
        } },
        { v = "1.5.2", date = "22/11/2026", titre = "AuraCore : demander les buffs", blocs = {
            { "h", "AuraCore (bêta)" },
            { "li", "Bouton « Demander les buffs » au-dessus du portrait : gris quand rien ne manque, illuminé dès qu'un buff manque ; déplaçable (Maj + glisser), raccourci clavier ou manette, /auracore buffs." },
            { "li", "Page « Buffs suivis » : tout ce que chaque classe peut donner, à cocher un par un, avec la couleur de chaque classe." },
            { "li", "Icônes absentes : intérieur estompé, cercle net, opacités réglables (liées ou non)." },
            { "li", "En combat : plus de doublons, plus d'icônes qui sautent quand un proc arrive, pistages écartés." },
            { "li", "Réglages rangés par rubriques, avec la mise en page des paramètres de QuestCore." },
            { "h", "QuestCore" },
            { "li", "Suites de quêtes dans le suivi : la quête en cours déroulée, les suivantes en gris, reliées par un trait." },
            { "li", "Ligne « Où » ou « À voir » sous les objectifs : qui laisse l'objet, où sont les créatures, qui reprend la quête." },
            { "li", "Parcours de donjon en quatre groupes (en cours, à rendre, à faire, fait) ; un parcours « Avant d'y aller » se complète tout seul." },
            { "li", "Carte : le détail ne se montre que zone par zone ; plus aucun repère mal placé (donjons, zones ajoutées par Forever). Un objectif sans lieu montre celui qui reprend la quête." },
            { "h", "Suite" },
            { "li", "Raccourci « Demander les buffs » dans le panneau des raccourcis." },
            { "li", "Fenêtres à onglets (AuraCore, Macros, Interface) avec la mise en page des paramètres de QuestCore." },
            { "li", "Couleurs de classe exactes du jeu partout, même sur le parchemin." },
            { "li", "LegacyCore : les personnages sans le nom de classe (la couleur la dit)." },
            { "d", "Contenu : CraftCore 0.35.2, QuestCore 0.34.2, MapCore 0.12.2, LegacyCore 0.7.2, AuraCore 0.9.1 (bêta)" },
        } },
        { v = "1.5.1", date = "21/11/2026", titre = "Nouveau : AuraCore (bêta)", blocs = {
            { "h", "Nouveau : AuraCore (bêta)" },
            { "li", "Un anneau discret autour du personnage, avec les icônes et l'anneau doré du jeu : vos améliorations, ce que vous vous mettez vous-même (aspect, aura, armure), et tout ce qui se déclenche." },
            { "li", "Nourriture, flacon et potion, puis les buffs que votre groupe peut vous donner, chacun dans un quart du cercle choisi : grisés s'ils manquent, en couleur s'ils sont actifs." },
            { "li", "Les effets nuisibles sur leur propre cercle, à l'intérieur ou à l'extérieur, sans jamais toucher l'anneau." },
            { "li", "Durée restante dans l'icône, à l'extérieur ou masquée ; cercle de durée dégressif ou progressif ; taille, rayon, opacité et disposition réglables." },
            { "li", "Aussi publié seul : il garde alors la même fenêtre et les mêmes réglages que la suite." },
            { "li", "Un bouton (page L'anneau), un raccourci ou /auracore buffs demande au groupe, en un seul message hors combat, les buffs qui manquent et qui peut les donner." },
            { "h", "MapCore" },
            { "li", "Nouveau point d'intérêt : les marchands de flèches et de balles (chasseurs, guerriers, voleurs)." },
            { "li", "Un guidage vers un PNJ ou un service trace des pointillés sur la carte, du personnage jusqu'à lui." },
            { "h", "Guidage" },
            { "li", "La flèche devient une boussole : un anneau, la flèche qui tourne autour, la distance et la durée estimée dessous." },
            { "h", "Suivis et manette" },
            { "li", "Les infobulles restent toujours au même endroit, contre la fenêtre (côté réglable)." },
            { "li", "À la manette, l'élément choisi clignote ; dans les quêtes, la croix passe de titre en titre, sans s'arrêter sur les onglets." },
            { "li", "Prendre le contrôle d'un suivi fermé le rouvre le temps du pilotage, puis le referme." },
            { "h", "QuestCore" },
            { "li", "Parcours de donjon : les étapes se rangent en trois groupes, En cours, À faire et Fait (en vert, cochées)." },
            { "li", "Une icône de donjon distingue les quêtes qui se font dans une instance ; l'infobulle dit lequel, et si la quête s'y prend. Les kits s'appellent désormais « Avant d'y aller »." },
            { "li", "Une longue-vue à côté de la petite carte montre la quête seule sur la carte ; les deux icônes sont toujours au même endroit, sous le titre." },
            { "li", "L'infobulle d'une quête prise dit qui la donne." },
            { "li", "Carte : plus de repères étirés sur tout le continent (donjons, zones ajoutées par Forever comme le Mont Hyjal)." },
            { "li", "Le bas du suivi ne garde que les boutons utiles (Trajet niveau seulement dans les quêtes, Supprimer seulement pour un parcours fini)." },
            { "li", "Correctifs : suivi vide avec trois boutons, erreurs en instance (valeurs cachées par le jeu)." },
            { "h", "CraftCore" },
            { "li", "Les fabrications rapides se suppriment (en deux temps), et le suivi Mes fabrications suit chaque modification aussitôt." },
            { "d", "Contenu : CraftCore 0.35.1, QuestCore 0.34.1, MapCore 0.12.1, LegacyCore 0.7.1, AuraCore 0.9.0 (bêta)" },
        } },
        { v = "1.5.0", date = "21/11/2026", titre = "CraftCore fabrique et vise plusieurs rangs", blocs = {
            { "h", "CraftCore : fabriquer" },
            { "li", "La fenêtre de métier du jeu s'ouvre en arrière-plan, invisible, quand un bouton Créer de CraftCore la demande. Elle se referme seule à la fin de la série ou dès que le personnage bouge. Ouverte par vous (K), elle reste normale." },
            { "li", "Chaque étape se compte : 0 / 5, 1 / 5… jusqu'à 5 / 5, puis passe en vert. La série s'arrête à la quantité demandée." },
            { "li", "Pas de fabrication partielle : Créer reste grisé tant que la récolte, les achats et la récupération ne sont pas faits, avec la raison à côté." },
            { "li", "Enchanter depuis CraftCore : choix de l'objet dans une petite fenêtre (jouable à la manette), puis enchantement direct. Si le jeu refuse, la fenêtre du métier s'ouvre sur la recette, avec les sacs et la fiche du personnage." },
            { "li", "Le message de félicitations attend la fin de toute la série." },
            { "h", "CraftCore : monter un métier" },
            { "li", "Trois rangs visés cumulables, chacun avec sa case : le rang assuré par vos composants (coché d'office), le rang atteignable avec vos recettes, et un rang de votre choix, qui suit les flèches." },
            { "li", "Les rangs visés se suivent sans doublon : ce qu'utilise le premier n'est pas recompté pour le suivant. Le détail par rang est indiqué à droite." },
            { "li", "Étapes dans l'ordre logique : récolter, acheter, récupérer, fabriquer les composants (jusqu'au minerai), monter le métier." },
            { "li", "Guider la récolte dit où mène la flèche, et utilise aussi les filons repérés sans pouvoir les miner." },
            { "h", "QuestCore" },
            { "li", "Même présentation dans toutes les pages : zones repliables, quêtes ouvertes d'un clic." },
            { "li", "Quêtes disponibles : XP à prendre par zone à votre niveau, et la suite complète d'une quête quand elle en fait partie." },
            { "li", "Une quête localisée sur la carte affiche d'abord un halo, puis clignote." },
            { "h", "Toute la suite" },
            { "li", "Textes explicatifs plus discrets, légendes colorées comme ce qu'elles décrivent." },
            { "li", "Valeurs entre flèches resserrées (jusqu'à 999)." },
            { "li", "Messages aussi dans l'onglet SagaCore de la discussion." },
            { "d", "Contenu : CraftCore 0.35.0, QuestCore 0.34.0, MapCore 0.12.0, LegacyCore 0.7.0" },
        } },
    } },
    { cle = "s1.1", titre = "1.1 à 1.4 : services, messages, charte et itinéraires", periode = "19/11 au 20/11/2026", resume = "Les services sur la carte de MapCore, la page Monter un métier, les messages de la suite dans la discussion, une charte graphique commune et les itinéraires dans le suivi des quêtes.", versions = {
        { v = "1.4.0", date = "20/11/2026", titre = "Itinéraires dans le suivi des quêtes", blocs = {
            { "h", "Suivi des quêtes et itinéraires" },
            { "li", "Deux onglets sur le côté du suivi : le suivi des quêtes, et l'itinéraire (boussole), qui s'active dès qu'un trajet existe." },
            { "li", "L'itinéraire a trois catégories : itinéraires (niveau, rendu, suites de quêtes), récolte (la tournée de MapCore) et donjons (prérequis)." },
            { "li", "Les étapes pas encore prises sont présentées comme des quêtes : niveau en couleur, XP, objectifs, infobulle complète. Les étapes faites disparaissent ; un parcours terminé se supprime d'un bouton." },
            { "li", "Plusieurs parcours peuvent être ouverts à la fois. Chaque étape peut être retirée de l'itinéraire, puis remise." },
            { "li", "Guider un parcours ouvre la carte de QuestCore sur la première étape, avec tout le trajet numéroté. Hors de portée de la flèche (autre continent), elle dit où aller. Fermer la fenêtre arrête ce guidage." },
            { "li", "Prérequis de donjon : le trajet se crée d'un bouton, le suivi s'ouvre dessus et la flèche part." },
            { "h", "Cartes" },
            { "li", "Les repères au même endroit ne s'empilent plus : ils sont posés côte à côte, dans QuestCore comme dans MapCore." },
            { "li", "Numéros d'étape dans un petit rond cerclé, en jaune vif, lisibles sur tous les fonds." },
            { "h", "CraftCore" },
            { "li", "Les stocks comptent ce qui attend dans les boîtes aux lettres : relevé à l'ouverture de la boîte, plus ce que vos personnages s'envoient entre eux. Nouvelle colonne Courrier, détail par personnage au survol." },
            { "li", "Le bouton Créer devient Lancer une fois le métier ouvert. Grisé, il dit ce qui manque dans les sacs, sans survol." },
            { "li", "Monter un métier : textes alignés et d'une seule taille, rang visé réglé par flèches (1 par 1 et 5 par 5), la liste des achats reste affichée et se coche quand l'objet est dans les sacs." },
            { "li", "Banque : la touche A de la manette lance Tout sortir." },
            { "h", "Toute la suite" },
            { "li", "Les fenêtres s'effacent presque entièrement dès que le personnage marche, et reviennent à l'arrêt." },
            { "li", "Plus de trait entre le menu de gauche et le contenu des fenêtres." },
            { "d", "Contenu : CraftCore 0.34.0, QuestCore 0.33.0, MapCore 0.11.0, LegacyCore 0.6.0" },
        } },
        { v = "1.3.1", date = "20/11/2026", titre = "Personnage retrouvé quand le royaume arrive vide", blocs = {
            { "p", "Correctif." },
            { "li", "Depuis la dernière mise à jour du jeu, le nom du royaume peut arriver vide. La suite ne retrouvait plus le personnage : suivis des quêtes et des fabrications vides, métiers absents, onglets manquants. Elle retient désormais le royaume connu et retrouve le personnage même dans ce cas. Aucune donnée n'était perdue." },
            { "d", "Contenu : CraftCore 0.33.1, QuestCore 0.32.1, MapCore 0.10.1, LegacyCore 0.5.1" },
        } },
        { v = "1.3.0", date = "20/11/2026", titre = "Charte graphique, fonds et réglage de l'interface", blocs = {
            { "li", "Nouvelle charte graphique pour toute la suite : chaque page commence par son titre, ses boutons d'action sur la même ligne, à droite ; listes déroulantes, valeurs et cases alignées sur le bord droit." },
            { "li", "Listes déroulantes lisibles partout à la place des boutons qui changeaient de valeur à chaque clic ; valeurs réglables entre deux flèches, à la souris comme à la manette." },
            { "li", "Nouveaux fonds : parchemins Alliance et Horde en trois tons (naturel, gris, doré), parchemin clair, roche grise ; panneau du menu bleu ou rouge, dépoli ou vif." },
            { "li", "Paramétrage de l'interface : un réglage par défaut selon votre faction, ou vos propres choix, enregistrables en compositions. Dans les Paramètres de CraftCore, les réglages généraux de la suite (Réglage de l'interface) et Options, Add-ons, Forever SagaCore." },
            { "li", "Options du jeu : une page Forever SagaCore, avec une sous-page par module (CraftCore, QuestCore, MapCore, Messages), des profils, et l'export ou l'import de vos réglages." },
            { "li", "Suivis des quêtes et des fabrications : une touche « Naviguer dans le suivi » (Options, Raccourcis, QuestCore ou CraftCore) pour les parcourir à la manette ; le guidage s'arrête seul à l'arrivée." },
            { "li", "QuestCore : les zones des quêtes disponibles se replient de nouveau ; titres harmonisés sur toutes les pages." },
            { "li", "CraftCore : Mes stocks, Recettes, Mes fabrications et Mes caisses ont leur titre et leurs actions sur la même ligne." },
            { "d", "Contenu : CraftCore 0.33.0, QuestCore 0.32.0, MapCore 0.10.0, LegacyCore 0.5.0" },
        } },
        { v = "1.2.1", date = "20/11/2026", titre = "La suite vous parle dans la discussion", blocs = {
            { "li", "Nouveau : la suite vous parle dans la discussion. Un onglet « SagaCore » s'ouvre dans le chat ; chaque add-on y parle en son nom, avec sa couleur et son icône, et des mots cliquables lancent l'action (créer l'itinéraire, guider, tout sortir de la banque...)." },
            { "li", "Chaque message se règle : actif ou non, où il s'affiche (onglet SagaCore, discussion générale, les deux, nulle part) et son texte, que vous pouvez réécrire. Réglages généraux de la suite, bouton « Messages dans la discussion », ou /sagacore messages." },
            { "li", "À la manette : /sagacore oui ou /sagacore non répond au dernier message (à mettre dans une macro)." },
            { "li", "QuestCore : assez de quêtes pour monter, niveau suivant proche, quête terminée, donjon accessible." },
            { "li", "CraftCore : commande reçue, composants réunis pour un objectif, composants à sortir de la banque, envoi prêt, rang visé atteint, récolte manquante, commande fabriquée." },
            { "li", "MapCore : arrivée à destination, équipement abîmé avec le réparateur le plus proche, autre personnage dans la zone." },
            { "li", "LegacyCore : défi de classe accompli, points d'héritage à dépenser, palier de métier, nouvelle classe sur le compte." },
            { "li", "CraftCore : la touche A de la manette fonctionne avec ConsolePort au panneau de la banque." },
            { "d", "Contenu : CraftCore 0.32.0, QuestCore 0.31.0, MapCore 0.9.0, LegacyCore 0.4.0" },
        } },
        { v = "1.2.0", date = "20/11/2026", titre = "Publication automatique sur CurseForge", blocs = {
            { "li", "La suite part sur CurseForge à chaque nouvelle version, en même temps que sur GitHub." },
            { "li", "CraftCore : la touche A de la manette marche à la banque avec ConsolePort." },
        } },
        { v = "1.1.2", date = "19/11/2026", titre = "CraftCore : page Monter un métier", blocs = {
            { "li", "CraftCore : nouvelle page « Monter un métier ». On choisit le rang visé, puis les étapes se suivent dans l'ordre : récupérer, acheter, récolter, fabriquer d'abord, monter le métier. Chaque étape a son bouton et se coche quand elle est faite." },
            { "li", "CraftCore : « Mes progressions » et l'onglet « Progression » ne font plus qu'une seule page. Les anciens projets de progression deviennent des rangs visés." },
            { "li", "CraftCore : le plan de progression fait toujours les recettes oranges d'abord et sépare les points sûrs des points probables." },
            { "li", "CraftCore : à la banque, le panneau se place à côté de la fenêtre de la banque, sur fond de cuir, et sort aussi les composants des rangs visés." },
            { "li", "CraftCore : à l'hôtel des ventes, la section « À acheter pour mes projets » lance la recherche de chaque composant manquant." },
            { "li", "CraftCore : les métiers principaux d'abord dans les onglets, puis Cuisine, Pêche et Secourisme. « Commandes » devient « Mes commandes »." },
            { "li", "CraftCore : le suivi de récolte aligne correctement les noms et les quantités." },
            { "d", "Contenu : CraftCore 0.31.0, QuestCore 0.30.2, MapCore 0.8.0, LegacyCore 0.3.2" },
        } },
        { v = "1.1.1", date = "19/11/2026", titre = "QuestCore attend Questie", blocs = {
            { "li", "QuestCore : « Mon histoire », les Donjons et les quêtes disponibles ne restent plus vides quand Questie se charge après la connexion." },
            { "li", "CraftCore : sur un bouton « Créer » grisé, l'infobulle s'affiche de nouveau et dit quels composants manquent et où ils se trouvent." },
            { "d", "Contenu : CraftCore 0.30.2, QuestCore 0.30.2, MapCore 0.8.0, LegacyCore 0.3.2" },
        } },
        { v = "1.1.0", date = "19/11/2026", titre = "MapCore : les services sur la carte", blocs = {
            { "li", "MapCore : services sur la carte (maîtres de classe et de métier, réparation, boîtes aux lettres, auberges, banques, maîtres de vol), filtres réunis sous la carte, continents en onglets, personnages en haut, halo puis clignotement de la destination." },
            { "li", "Partout où la suite guide (marchand, récolte, quête), la carte s'ouvre sur la destination." },
            { "li", "Chaque add-on rouvre là où on l'avait laissé ; `/sagacore` rouvre la suite." },
            { "li", "Manette : navigation revue dans MapCore." },
            { "li", "Moins de doublons de quêtes et de boîtes aux lettres sur les cartes." },
            { "d", "Contenu : CraftCore 0.30.2, QuestCore 0.30.2, MapCore 0.8.0, LegacyCore 0.3.2" },
        } },
    } },
    { cle = "s1.0", titre = "1.0 : les débuts", periode = "19/11 au 19/11/2026", resume = "La première suite complète : CraftCore, QuestCore, MapCore et LegacyCore ensemble. Les versions 1.0.1 à 1.0.14 sont des corrections rapides après la sortie, puis le nouveau nom, Forever SagaCore, et sept langues.", versions = {
        { v = "1.0.14", date = "19/11/2026", titre = "Sept langues au choix", blocs = {
