        { v = "1.0.7", date = "19/11/2026", titre = "Nouveau nom : Forever SagaCore", blocs = {
            { "p", "Nouveau nom : Forever SagaCore. CraftCore 0.29.6, QuestCore 0.29.8, MapCore 0.6.3, LegacyCore 0.2.8." },
