        { v = "1.0.5", date = "19/11/2026", titre = "Corrections de CraftCore, QuestCore et LegacyCore", blocs = {
            { "d", "Contenu : CraftCore 0.29.4, QuestCore 0.29.5, MapCore 0.6.1, LegacyCore 0.2.6" },
        } },
        { v = "1.0.4", date = "19/11/2026", titre = "Onglets de la suite remplis par leur icône", blocs = {
            { "p", "Onglets de la suite : l'icône remplit tout l'intérieur de l'onglet, comme les onglets de métier." },
            { "d", "Contenu : CraftCore 0.29.3, QuestCore 0.29.4, MapCore 0.6.1, LegacyCore 0.2.5" },
